using System.Security.Claims;
using Microsoft.AspNetCore.Components.Authorization;

namespace sv_930e10d1807b4cea8305060a11acfe29.Auth;

public class HardcodedAuthenticationStateProvider : AuthenticationStateProvider
{
    private static readonly Task<AuthenticationState> _authState = Task.FromResult(
        new AuthenticationState(new ClaimsPrincipal(new ClaimsIdentity(
            new[]
            {
                new Claim(ClaimTypes.Name, "bob@example.com"),
                new Claim(ClaimTypes.Email, "bob@example.com"),
                new Claim(ClaimTypes.Role, "User"),
                new Claim(ClaimTypes.Role, "Editor"),
            },
            authenticationType: "Hardcoded"))));

    public override Task<AuthenticationState> GetAuthenticationStateAsync() => _authState;
}

using System.Security.Claims;
using Microsoft.AspNetCore.Components;
using Microsoft.AspNetCore.Components.Authorization;
using Microsoft.AspNetCore.Components.Web;
using sv_930e10d1807b4cea8305060a11acfe29.Client;

namespace sv_930e10d1807b4cea8305060a11acfe29.Auth;

/// <summary>
/// Subscribes to auth state on the server and persists user info
/// so the WebAssembly client can reconstruct the ClaimsPrincipal.
/// </summary>
public class PersistingAuthenticationStateProvider : AuthenticationStateProvider, IDisposable
{
    private readonly PersistentComponentState _state;
    private readonly AuthenticationStateProvider _underlying;
    private PersistingComponentStateSubscription _subscription;
    private Task<AuthenticationState>? _authTask;

    public PersistingAuthenticationStateProvider(
        PersistentComponentState state,
        [FromKeyedServices("Hardcoded")] AuthenticationStateProvider underlying)
    {
        _state = state;
        _underlying = underlying;
        _subscription = state.RegisterOnPersisting(OnPersistingAsync, RenderMode.InteractiveWebAssembly);
    }

    public override Task<AuthenticationState> GetAuthenticationStateAsync()
    {
        _authTask ??= _underlying.GetAuthenticationStateAsync();
        return _authTask;
    }

    private async Task OnPersistingAsync()
    {
        var authState = await GetAuthenticationStateAsync();
        var principal = authState.User;

        if (principal.Identity?.IsAuthenticated == true)
        {
            var userInfo = new UserInfo
            {
                Name = principal.FindFirst(ClaimTypes.Name)?.Value ?? "",
                Roles = principal.FindAll(ClaimTypes.Role).Select(c => c.Value).ToArray(),
            };
            _state.PersistAsJson(nameof(UserInfo), userInfo);
        }
    }

    public void Dispose()
    {
        _subscription.Dispose();
    }
}

namespace sv_930e10d1807b4cea8305060a11acfe29.Client;

/// <summary>
/// Serializable user info persisted from server to WebAssembly client.
/// </summary>
public class UserInfo
{
    public string Name { get; set; } = "";
    public string[] Roles { get; set; } = [];
}

using System.Security.Claims;
using Microsoft.AspNetCore.Components;
using Microsoft.AspNetCore.Components.Authorization;

namespace sv_930e10d1807b4cea8305060a11acfe29.Client;

/// <summary>
/// Client-side AuthenticationStateProvider that reads persisted user info
/// from the server via PersistentComponentState.
/// </summary>
public class PersistentAuthenticationStateProvider : AuthenticationStateProvider
{
    private static readonly AuthenticationState _unauthenticated =
        new(new ClaimsPrincipal(new ClaimsIdentity()));

    private readonly Task<AuthenticationState> _authStateTask;

    public PersistentAuthenticationStateProvider(PersistentComponentState state)
    {
        if (state.TryTakeFromJson<UserInfo>(nameof(UserInfo), out var userInfo) && userInfo is not null)
        {
            var claims = new List<Claim>
            {
                new(ClaimTypes.Name, userInfo.Name),
                new(ClaimTypes.Email, userInfo.Name),
            };
            foreach (var role in userInfo.Roles)
            {
                claims.Add(new Claim(ClaimTypes.Role, role));
            }

            var identity = new ClaimsIdentity(claims, authenticationType: "Persisted");
            _authStateTask = Task.FromResult(new AuthenticationState(new ClaimsPrincipal(identity)));
        }
        else
        {
            _authStateTask = Task.FromResult(_unauthenticated);
        }
    }

    public override Task<AuthenticationState> GetAuthenticationStateAsync() => _authStateTask;
}

